// Hand-written - NOT auto-generated.
//
// The component compiler generates the TextPlane partial class in
// SampleScripts.codegen/TextPlane.cs (from SampleScripts~/DragControls/TextPlane.ts) with a field
// of this type, align, but it does not emit enum declarations from TypeScript enums - only class
// members. So the enum itself has to exist on the C# side by hand.
//
// Keep names and values identical to TextPlaneAlign in TextPlane.ts.
namespace Needle.Typescript.GeneratedComponents
{
	public enum TextPlaneAlign
	{
		Left = 0,
		Center = 1,
		Right = 2,
	}
}
